/* Counts and preferences contain no post content or health data. */
window.NeoCommunityAlerts=(()=>{
 let owner='',info=null,revision=0,busy=false,last=0,seenPending=false,changes=0,directUnread=0,directThreads=[],unsubscribe=null,liveTimer=null,liveRevision=null,livePending={group:false,direct:false};
 const cloud=()=>window.NeoCloud;
 function paint(){for(const node of document.querySelectorAll('[data-message-badge]')){const count=node.dataset.messageBadge==='direct'?directUnread:Math.max(0,Number(info?.unread)||0)+(node.dataset.messageBadge==='all'?directUnread:0);node.hidden=!count;node.textContent=count>99?'99+':String(count)}const homeCount=document.querySelector('[data-community-home-count]'),homeText=document.querySelector('[data-community-home-text]');if(homeCount)homeCount.textContent=info?.total>0?`${Number(info.total).toLocaleString('pt-BR')} mensagens publicadas`:'Um espaço para trocar experiências';if(homeText)homeText.textContent=info?.unread>0?`${info.unread} novidades esperam por você. Entre na conversa.`:'Compartilhe suas conquistas, acompanhe conversas e descubra novos materiais.';const button=document.getElementById('communityIcon');if(!button)return;const badge=button.querySelector('.community-badge');const total=Math.max(0,Number(info?.total)||0),unread=button.dataset.supportShortcut==='true'?directUnread:Math.max(0,Number(info?.unread)||0)+directUnread;if(badge){badge.hidden=!unread;badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('has-news',unread>0)}button.setAttribute('aria-label',button.dataset.supportShortcut==='true'?`Atendimento: ${directUnread} mensagens novas`:total?`Comunidade: ${total} mensagens publicadas, ${unread} novas`:'Comunidade');}
 async function refresh(user,force=false){const key=user?.id||'';if(key!==owner){unsubscribe?.();unsubscribe=null;if(liveTimer)clearTimeout(liveTimer);liveRevision=null;livePending={group:false,direct:false};owner=key;revision++;info=null;directUnread=0;directThreads=[];last=0;busy=false;seenPending=false;paint();if(owner&&cloud()?.watchMessages){try{unsubscribe=cloud().watchMessages(value=>{livePending.group=livePending.group||!liveRevision||value.group_revision!==liveRevision.group_revision;livePending.direct=livePending.direct||!liveRevision||value.direct_revision!==liveRevision.direct_revision;liveRevision=value;if(liveTimer)clearTimeout(liveTimer);liveTimer=setTimeout(()=>{const detail=livePending;livePending={group:false,direct:false};refresh(cloud()?.user,true);document.dispatchEvent(new window.CustomEvent('neo:messages',{detail}))},80)},state=>{if(state==='SUBSCRIBED'){refresh(cloud()?.user,true);document.dispatchEvent(new window.CustomEvent('neo:messages',{detail:{group:true,direct:true}}))}})}catch{}}}if(!owner||!cloud()?.communityActivity||busy||(!force&&Date.now()-last<4500))return;busy=true;const token=revision,change=changes;try{const [group,direct]=await Promise.allSettled([cloud().communityActivity('status'),cloud().support?cloud().support('list'):Promise.resolve(null)]);if(token!==revision)return;if(group.status==='fulfilled'&&change===changes)info=group.value;if(direct.status==='fulfilled'){directThreads=direct.value?.threads||[];directUnread=directThreads.reduce((sum,t)=>sum+Math.max(0,Number(t.unread)||0),0)}last=Date.now();paint()}catch{if(token===revision)last=Date.now()}finally{if(token===revision)busy=false}}
 async function seen(activity){if(!owner||seenPending||!activity?.member||(info?.latest===activity.latest&&info?.unread===0))return;info=activity;paint();if(!activity.unread)return;seenPending=true;changes++;const token=revision;try{const next=await cloud().communityActivity('seen',{through:activity.latest});if(token!==revision)return;info=next;paint()}catch{}finally{if(token===revision)seenPending=false}}
 const panel=()=>`<section class="card community-notification-panel" data-community-notifications><h2>Avisos da comunidade</h2><p>Receba avisos de novas mensagens no Grupo e em suas conversas privadas. Textos, nomes e anexos não aparecem na notificação.</p><p data-community-alert-status role="status">${!info?'Carregando a preferência de avisos…':info.push_enabled?'Avisos da comunidade ativados na conta.':'Avisos da comunidade desativados na conta.'} ${window.NEO_CONFIG?.pushVapidPublicKey?'A entrega depende da permissão de notificações do aparelho.':'O envio ao celular ainda depende da configuração do servidor.'}</p><button class="primary" data-community-alert="toggle" ${!info?'disabled':''}>${info?.push_enabled?'Desativar':'Ativar'} avisos da comunidade</button><button class="text-btn" data-community-alert="close">Fechar</button></section>`;
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-community-alert]');if(!button)return;const root=button.closest('[data-community-notifications]');if(button.dataset.communityAlert==='close'){root.remove();return}if(!owner)return;const token=revision;changes++;button.disabled=true;try{const next=await cloud().communityActivity('preferences',{enabled:!info?.push_enabled});if(token!==revision)return;info=next;root.outerHTML=panel();paint()}catch(err){if(token===revision){const status=root.querySelector('[data-community-alert-status]');status.textContent=['PGRST202','42883'].includes(err.code)?'Falta executar a atualização de avisos no Supabase.':err.message;button.disabled=false}}});
 setInterval(()=>{if(document.visibilityState==='visible'&&navigator.onLine!==false)refresh(cloud()?.user)},5000);
 window.addEventListener('focus',()=>refresh(cloud()?.user,true));
 const home=()=>`<section class="card community-home" aria-label="Comunidade NeoPep"><div class="community-home-icon" aria-hidden="true">✦</div><div class="community-home-copy"><span class="eyebrow">SUA COMUNIDADE</span><h2>Sua evolução também conecta.</h2><p data-community-home-text>${info?.unread>0?`${Number(info.unread)} novidades esperam por você. Entre na conversa.`:'Compartilhe suas conquistas, acompanhe conversas e descubra novos materiais.'}</p><span class="community-home-identity">Entre com o primeiro nome do perfil. Seus registros continuam privados.</span><small data-community-home-count>${info?.total>0?`${Number(info.total).toLocaleString('pt-BR')} mensagens publicadas`:'Um espaço para trocar experiências'}</small></div><button class="primary" data-go="comunidade">Abrir comunidade <span aria-hidden="true">↗</span></button></section>`;
 return {refresh,seen,panel,home,paint,snapshot:()=>({group:Math.max(0,Number(info?.unread)||0),direct:directUnread,threads:directThreads})};
})();
